func (pq *PlayerQuery) loadLimits(ctx context.Context, query *PlayerLimitQuery, nodes []*Player, init func(*Player), assign func(*Player, *PlayerLimit)) error {
	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[string]*Player)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
	}
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(playerlimit.FieldPlayerID)
	}
	query.Where(predicate.PlayerLimit(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(player.LimitsColumn), fks...))
	}))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.PlayerID
		node, ok := nodeids[fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "player_id" returned %v for node %v`, fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}
